import { useParams, Link } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { getPosts } from '../utils/storage';
import { getAuthorName } from '../utils/auth';
import ReactMarkdown from 'react-markdown';
import './styles/PostDetail.scss';

function PostDetail() {
  const { id } = useParams();
  const allPosts = getPosts();
  const post = allPosts.find((p) => p.id.toString() === id);

  const author = getAuthorName(); // logged-in editor

  const [likes, setLikes] = useState(0);
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');
  const [fallbackImage, setFallbackImage] = useState('');

  // Generate fallback image based on post title
  useEffect(() => {
    if (post && !post.image) {
      const encoded = encodeURIComponent(post.title);
      const url = `https://source.unsplash.com/featured/?${encoded}`;
      setFallbackImage(url);
    }
  }, [post]);

  useEffect(() => {
    if (!post) return;
    const savedLikes = parseInt(localStorage.getItem(`likes-${id}`)) || 0;
    const savedComments = JSON.parse(localStorage.getItem(`comments-${id}`)) || [];
    setLikes(savedLikes);
    setComments(savedComments);
  }, [id, post]);

  const handleLike = () => {
    const updated = likes + 1;
    localStorage.setItem(`likes-${id}`, updated.toString());
    setLikes(updated);
  };

  const handleCommentSubmit = (e) => {
    e.preventDefault();
    if (!newComment.trim()) return;

    const entry = {
      name: author || 'Anonymous',
      text: newComment,
      time: new Date().toISOString(),
    };

    const updated = [...comments, entry];
    localStorage.setItem(`comments-${id}`, JSON.stringify(updated));
    setComments(updated);
    setNewComment('');
  };

  if (!post) {
    return (
      <div className="container">
        <h2>Post not found</h2>
        <Link to="/">← Back to Home</Link>
      </div>
    );
  }

  return (
    <div className="post-detail container">
      <h1>{post.title}</h1>

      <img
        src={post.image || fallbackImage}
        alt="cover"
        className="post-detail__image"
      />

      <p className="post-detail__meta">
        <strong>Author:</strong> {post.author} &nbsp; | &nbsp;
        <strong>Category:</strong> {post.category}
      </p>

      <div className="post-detail__content">
        <ReactMarkdown>{post.content}</ReactMarkdown>
      </div>

      <div className="post-detail__likes">
        <button onClick={handleLike}>❤️ Like</button> {likes} likes
      </div>

      <div className="post-detail__comments">
        <h3>Comments</h3>
        {comments.length === 0 ? <p>No comments yet.</p> : (
          <ul>
            {comments.map((c, i) => (
              <li key={i}>
                <strong>{c.name}</strong>: {c.text}
              </li>
            ))}
          </ul>
        )}

        <form onSubmit={handleCommentSubmit}>
          <textarea
            placeholder="Write a comment..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            rows="3"
            required
          />
          <button type="submit">Post Comment</button>
        </form>
      </div>

      <Link to="/">← Back to Home</Link>
    </div>
  );
}

export default PostDetail;
